class InvalidWithdrawalException extends Exception{InvalidWithdrawalException(String m){super(m);}}class InsufficientFundsException extends Exception{InsufficientFundsException(String m){super(m);}}public class AtmWithdrawal{static double withdraw(double balance,String text)throws InvalidWithdrawalException,InsufficientFundsException{double amount;try{amount=Double.parseDouble(text);}catch(NumberFormatException e){throw new InvalidWithdrawalException("Amount must be numeric");}if(amount<=0)throw new InvalidWithdrawalException("Amount must be positive");if(amount>balance)throw new InsufficientFundsException("Insufficient balance");return balance-amount;}public static void main(String[]x){for(String s:new String[]{"100","-5","abc","900"}){try{System.out.println(s+" -> balance "+withdraw(500,s));}catch(InvalidWithdrawalException|InsufficientFundsException e){System.out.println(s+" -> "+e.getMessage());}finally{System.out.println("Transaction attempt finished");}}}}